                                                  "description":  "\u003cp\u003e\u003cstrong\u003eঅর্ডার করার আগে ভালোভাবে পড়ে নিন!\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eভুলেও গেস্ট আইডিতে\u0026nbsp;অর্ডার করবেন না।\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u0026nbsp;\u003c/p\u003e\u003cp\u003eগুরুত্বপূর্ণ 👇👇\u003c/p\u003e\u003cp\u003e\u0026nbsp;\u003c/p\u003e\u003cp\u003e২৪ ঘন্টায় ১ টি হবে শুধু, ১ টির বেশি অর্ডার করলে লাইক যাবেনা এবং টাকাও ফেরত পাবেন না\u003c/p\u003e\u003cp\u003e\u0026nbsp;\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eএক আইডিতে প্রতিদিন একবার \u0026nbsp;নিতে পারবেন। একদিনে একই আইডিতে বার বার অর্ডার করলে টাকা ফেরত দেওয়া হবে না।\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u0026nbsp;\u003c/p\u003e\u003cp\u003e\u003cstrong\u003eডেলিভারি টাইম: সাধারণত ১ মিনিটের মধ্যে ডেলিভারি দেওয়া হয়। তবে নির্ধারিত সময়ের মধ্যে না পেলে, দয়া করে আমাদের টেলিগ্রাম সাপোর্টে মেসেজ দিন।\u003c/strong\u003e\u003c/p\u003e",
